import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void rms_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2
) {
    const int batch_idx = blockIdx.x;
    const int feature_idx = threadIdx.x;

    if (batch_idx >= batch_size) return;

    // Shared memory for reduction
    extern __shared__ float shared_data[];

    const int elements_per_batch = features * dim1 * dim2;
    const int batch_offset = batch_idx * elements_per_batch;

    // Initialize shared memory
    float sum = 0.0f;

    // Compute sum of squares for this feature dimension
    if (feature_idx < features) {
        const int feature_offset = feature_idx * dim1 * dim2;
        for (int i = 0; i < dim1 * dim2; ++i) {
            const int idx = batch_offset + feature_offset + i;
            const float val = __half2float(input[idx]);
            sum += val * val;
        }
        shared_data[feature_idx] = sum;
    } else {
        shared_data[feature_idx] = 0.0f;
    }

    __syncthreads();

    // Reduce across features to compute RMS
    float rms_sum = 0.0f;
    for (int i = 0; i < features; ++i) {
        rms_sum += shared_data[i];
    }

    const float rms = sqrtf(rms_sum / (features * dim1 * dim2) + eps);

    // Normalize and write back
    __syncthreads();

    for (int i = 0; i < dim1 * dim2; ++i) {
        const int idx = batch_offset + i;
        const float val = __half2float(input[idx]);
        output[idx] = __float2half(val / rms);
    }
}

// Optimized version using warp-level primitives
__global__ void rms_norm_kernel_optimized(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2
) {
    const int batch_idx = blockIdx.x;
    const int tid = threadIdx.x;

    if (batch_idx >= batch_size) return;

    const int elements_per_batch = features * dim1 * dim2;
    const int batch_offset = batch_idx * elements_per_batch;

    // Each thread processes one element in the batch
    const int total_elements = elements_per_batch;

    // Compute RMS for the entire batch
    float sum = 0.0f;

    // Use cooperative loading and reduction for better performance
    for (int i = tid; i < total_elements; i += blockDim.x) {
        const float val = __half2float(input[batch_offset + i]);
        sum += val * val;
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // Only first thread computes final RMS
    if (tid == 0) {
        const float rms = sqrtf(sum / total_elements + eps);

        // Normalize all elements in the batch
        for (int i = 0; i < total_elements; ++i) {
            const float val = __half2float(input[batch_offset + i]);
            output[batch_offset + i] = __float2half(val / rms);
        }
    }
}
"""

def compile_and_run():
    # Load the CUDA extension
    module = load_inline(
        name="rms_norm_cuda",
        cpp_sources=[],
        cuda_sources=cuda_source,
        functions=["rms_norm_kernel_optimized"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, num_features: int, eps: float = 1e-5):
            super(ModelNew, self).__init__()
            self.num_features = num_features
            self.eps = eps

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            # Ensure input is float16
            if x.dtype != torch.float16:
                x = x.to(torch.float16)

            batch_size, features, dim1, dim2 = x.shape

            # Allocate output tensor
            output = torch.empty_like(x)

            # Launch kernel
            grid_size = batch_size
            block_size = min(1024, features * dim1 * dim2)

            # Use optimized kernel
            module.rms_norm_kernel_optimized(
                x.contiguous(),
                output,
                self.eps,
                batch_size,
                features,
                dim1,
                dim2
            )

            return output

    return ModelNew

# Create the model class
ModelNew = compile_and_run()

